import importlib.util, json

def load(path, name):
    spec=importlib.util.spec_from_file_location(name,path)
    m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m); return m

for label,path in [('candidate','openlibrary/utils/compress.py'),('baseline','baseline/openlibrary/utils/compress.py')]:
    m=load(path,'compress_'+label)
    probes={}
    for q, fn in {
      'c1': lambda: (lambda c: c.decompress(c.compress('second')))( (lambda c: (c.compress('first'), c)[1])(m.Compressor('seed')) ),
      'c2': lambda: (lambda c: c.decompress(c.compress('你好')))(m.Compressor('seed')),
      'c3': lambda: (lambda c: c.decompress(c.compress('ascii')))(m.Compressor('seed')),
      'c4': lambda: (lambda c: c.decompress(c.compress('')))(m.Compressor('seed')),
    }.items():
      try: probes[q]={'value':fn()}
      except Exception as e: probes[q]={'exception':type(e).__name__, 'text':str(e)}
    print(label, json.dumps(probes, ensure_ascii=False, sort_keys=True))
